// S04 design interaction only: local editable forms and source-labelled manual examples.
// No product Commands/Engine/Host/Agent is implemented or called by this prototype.
import { SceneView } from './scene-view.js';
const D=window.S04_DATA, $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy=v=>structuredClone(v), frame=id=>D.frames.find(f=>f.id===id);
const seed=()=>{const p={title:'控制盒厂房',dimensions:[24,16,4],devices:[
  {id:'A01',name:'控制盒装配台',model:'assembly',x:8,y:5,z:0,yaw:0,version:'0.1.0'},
  {id:'ROB01',name:'夹爪搬运机器人',model:'robot',x:10.7,y:5,z:0,yaw:0,version:'0.1.0'},
  {id:'CV01',name:'输送带',model:'conveyor',x:13,y:5,z:0,yaw:0,version:'0.1.0'},
  {id:'I01',name:'视觉检查台',model:'inspection',x:16,y:5,z:0,yaw:0,version:'0.1.0'},
  {id:'CV02',name:'装箱前输送带',model:'conveyor',x:18,y:5,z:0,yaw:0,version:'0.1.0'},
  {id:'PK01',name:'人工装箱台',model:'assembly',x:20,y:5,z:0,yaw:0,version:'0.1.0'},
  {id:'P01',name:'纸盒封装台',model:'sealer',x:22,y:5,z:0,yaw:0,version:'0.1.0'},
  {id:'FG01',name:'成品托盘（接受资源）',model:'pallet',x:23.4,y:5,z:0,yaw:0,version:'0.1.0',visual_role:'acceptance_resource'},
  {id:'R01',name:'返工台',model:'assembly',x:16,y:10,z:0,yaw:180,version:'0.1.0'}],
  connections:[['A01','ROB01'],['ROB01','CV01'],['CV01','I01'],['I01','CV02'],['CV02','PK01'],['PK01','P01'],['P01','FG01'],['I01','R01'],['R01','I01']],
  order:{product:'控制盒',version:'1.0.0',quantity:6,unit:'piece',due:500},arrivals:[{id:'ARR01',at:10,quantity:6},{id:'ARR02',at:20,quantity:6}],
  supply:{item:'半成品控制盒',quantity:120,loading:10,outbound:60,unloading:10,returning:60},
  device:{behavior:'operation_ref',module:'community.control-box-assembly',version:'0.1.0',duration:40,operator:'OP01',capacity:1},
  goal:{target:2,window:300,width:24,length:16,height:4,unit:'piece',destination:'FG01',calendar:'CAL01',template:'purchased-assembly',allowRepair:true},
  paper:{mechanism:'tuck_carton',width:160,depth:100,height:80,thickness:0.5,productRevision:'1.0.0',angle:0,outcome:'pass',ack:false,bound:false},
  definitions:[],lineMembers:['A01','ROB01','CV01','I01','CV02','PK01','P01','R01'],
  media:{mode:'phase_local',phase:'auto',clips:['阶段起姿态','加工准备','加工动作','阶段终姿态'],u:0,tags:[],imageAsset:null}};p.instanceState=Object.fromEntries(p.devices.map(d=>[d.id,{config:copy(p.device),media:copy(p.media)}]));return p;};
const S={frame:new URLSearchParams(location.search).get('frame')||'VP05',flow:'VF-01',project:seed(),revision:1,savedRevision:0,form:null,undo:[],redo:[],canvas:'line',lod:'detailed',selected:'A01',lineSelected:false,tool:'select',timelineVisible:true,descriptionVisible:true,dock:160,descriptionWidth:300,leftVisible:true,rightVisible:true,leftWidth:256,rightWidth:400,axis:'factory',axisWindow:[0,600],expanded:false,source:'input',selectedEvent:'ARR02',viewTime:0,run:null,compute:null,play:false,pendingSeek:null,seekToken:0,agent:{preview:null,built:false,rounds:0,scenario:'initial',stop:null,accepted:null},taskLog:[],printFormat:'HTML',conflict:false,adoption:{version:'0.1.0',newIds:true,reuse:true,seed:false,orders:false},packResult:null,selectedUnit:'006'};
S.newProjectApproved=S.frame==='VP01';
let toastTimer, imageAsset=null, moveDrag=null;
const view=new SceneView($('scene'), {select:id=>selectDevice(id), move:(id,x,y)=>moveDevice(id,x,y), zoom:distance=>{if($('auto-lod').checked){S.lod=distance>45?'region':distance>27?'simplified':'detailed';view.setLOD(S.lod);}}});
const btn=(label,action,primary=false,disabled=false)=>`<button data-action="${action}" ${primary?'class="primary"':''} ${disabled?'disabled':''}>${label}</button>`;
const msg=(text,kind='')=>`<div class="message ${kind}">${text}</div>`;
function row(label,key,value,unit='',readonly=false,scope='form'){return `<label class="row"><span>${label}</span><input data-field="${key}" data-scope="${scope}" value="${esc(value)}" ${readonly?'readonly':''} aria-label="${label}"><span class="unit">${unit}</span></label>`;}
function table(head,rows){return `<table class="table"><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function section(title,html){return `<section class="section"><h4>${title}</h4><div class="body">${html}</div></section>`;}
function notice(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',2500);}
function log(action,detail){S.taskLog.push({action,detail,prototype_revision:S.revision,product_API_called:false});}
function bindSelectedInstance(){if(!S.project.devices.some(d=>d.id===S.selected))return;S.project.instanceState??={};if(!S.project.instanceState[S.selected]){const p=seed();S.project.instanceState[S.selected]={config:copy(p.device),media:copy(p.media)};}const i=S.project.instanceState[S.selected];S.project.device=i.config;S.project.media=i.media;imageAsset=i.media.imageAsset;}
function edit(kind){if(S.form?.kind===kind)return S.form.data;const data=kind==='pose'?copy(S.project.devices.find(d=>d.id===S.selected)):kind==='inputs'?{order:copy(S.project.order),arrivals:copy(S.project.arrivals)}:copy(S.project[kind]);S.form={kind,data,base:S.revision,dirty:false};return data;}
function paperInput(p){return Object.fromEntries(Object.entries(p).filter(([k])=>!['angle','outcome','ack','bound'].includes(k)));}
function paperMatches(p=S.project.paper){return !!S.packResult&&JSON.stringify(S.packResult.input)===JSON.stringify(paperInput(p));}
function paperConsumerMatches(){return !!S.project.order.version&&S.packResult?.productRevision===S.project.order.version;}
function invalidatePaper(){S.project.paper.ack=false;S.project.paper.bound=false;}
function recordEdit(){S.undo.push(copy(S.project)); S.redo=[];}
function markDirectEdit(){S.revision++;$('save-indicator').textContent=' · 未保存';$('status').textContent=`原型草稿r${S.revision} | 草稿已修改，尚未保存`;if(window.S04_STATE)window.S04_STATE.revision=S.revision;}
function commit(kind,data,targetId=S.selected){const previousOrderVersion=S.project.order.version;recordEdit();if(kind==='pose'){const {x,y,z,yaw}=data;Object.assign(S.project.devices.find(d=>d.id===targetId),{x,y,z,yaw});}else if(kind==='device'){S.project.instanceState[S.selected].config=copy(data);S.project.device=S.project.instanceState[S.selected].config;}else if(kind==='inputs'){S.project.order=copy(data.order);S.project.arrivals=copy(data.arrivals);}else if(kind==='paper'){const {ack,bound}=S.project.paper;S.project.paper={...copy(data),ack,bound};}else S.project[kind]=copy(data);if((kind==='paper'&&!paperMatches())||S.project.order.version!==previousOrderVersion)invalidatePaper();S.revision++;log('local_prototype_apply',kind);view.setProject(S.project);}
function restoreDraft(saved){const current=copy(S.project.paper),previousTarget=packagingTargetId();S.project=saved;if(!S.project.devices.some(d=>d.id===S.selected))S.selected=S.project.devices[0]?.id||'';S.lineSelected=S.lineSelected&&S.project.lineMembers.length>0;S.connectSource=null;S.clipSelection=null;if(S.paperBindingTargetId&&!S.project.devices.some(d=>d.id===S.paperBindingTargetId))S.paperBindingTargetId=null;const sameTarget=previousTarget===packagingTargetId();const same=JSON.stringify(paperInput(current))===JSON.stringify(paperInput(S.project.paper));S.project.paper.ack=current.ack&&sameTarget&&same&&paperMatches()&&paperConsumerMatches();S.project.paper.bound=current.bound&&sameTarget&&same&&paperMatches()&&paperConsumerMatches()&&packagingTargets().some(d=>d.id===packagingTargetId());S.form=null;S.revision++;render();}
function apply(){if(!S.form?.dirty){notice('没有未应用更改');return true;}if(S.form.base!==S.revision){conflictDialog();return false;}const f=S.form, p=f.kind==='inputs'?f.data.order:f.data;
  if(['pose','goal','paper','device','supply','order','inputs'].includes(f.kind)){
    const required=f.kind==='goal'?[]:f.kind==='pose'?['x','y','z']:f.kind==='paper'?['width','depth','height','thickness']:f.kind==='device'?['duration','operator']:f.kind==='supply'?['quantity','loading','outbound','unloading','returning']:['quantity'];
    const missing=required.filter(k=>p[k]===''||p[k]===null||p[k]===undefined||(['target','window','width','length','height','thickness','quantity'].includes(k)&&!(Number(p[k])>0)));
    if(missing.length){notice('必需项未完整：'+missing.join('、'));showDialog('输入缺项',msg('补充 '+missing.join('、')+'；不把未知值填成0。','error')+btn('返回修改','dialog-close'));return false;}}
  const numeric={pose:['x','y','z','yaw'],goal:['target','window','width','length','height'],paper:['width','depth','height','thickness'],device:['duration','capacity'],supply:['quantity','loading','outbound','unloading','returning'],order:['quantity','due'],inputs:['quantity','due']}[f.kind]||[];
  const invalid=numeric.filter(k=>p[k]!==''&&p[k]!==null&&p[k]!==undefined&&!Number.isFinite(p[k]));
  if(invalid.length){showDialog('无效数字',msg('必须为有限数字：'+invalid.join('、')+'；未提交字段和当前工程保持。','error')+btn('返回修改','dialog-close'));return false;}
  const nonnegative=f.kind==='device'?['duration','capacity']:f.kind==='supply'?['loading','outbound','unloading','returning']:[];if(nonnegative.some(k=>p[k]<0)){notice('工时、容量和各段运输耗时不得为负数；未应用字段保留');return false;}if(f.kind==='device'&&p.capacity!==''&&p.capacity!==null&&!Number.isInteger(p.capacity)){notice('离散接受容量必须为非负整数；未应用字段保留');return false;}
  const arrivals=f.kind==='inputs'?f.data.arrivals:f.kind==='arrivals'?f.data:null;
  if(arrivals?.some(a=>!Number.isFinite(a.at)||a.at<0||!Number.isFinite(a.quantity)||a.quantity<0)){notice('到料时点/数量须是非负已知值；字段保留');return false;}
  if(f.kind==='pose'&&(p.x<0||p.y<0||p.x>S.project.dimensions[0]||p.y>S.project.dimensions[1])){notice('位置超出声明场地；草稿保留');return false;}
  commit(f.kind,f.data);S.form=null;notice('已应用到原型草稿；尚未保存');render();return true;}
function discard(){S.form=null;render();notice('已放弃表单更改，未取消任何计算任务');}
function showDialog(title,html){$('dialog-content').innerHTML=`<h2>${title}</h2>${html}`;$('dialog').showModal();}
function conflictDialog(){showDialog('RevisionConflict · 原型冲突示例',msg(`表单基于r${S.form.base}，当前草稿为r${S.revision}。字段保留，未部分应用。`,'error')+btn('重新核对并保持字段','conflict-rebase')+btn('留在当前','dialog-close'));
  log('conflict_shown',{base:S.form.base,current:S.revision});}
function go(id,force=false){if(S.form?.dirty&&!force){S.pendingFrame=id;showDialog('离开前处理未应用字段',msg('应用、丢弃或留在当前。应用不是写入磁盘，丢弃不取消任务。')+`<div class="actions">${btn('应用后离开','leave-apply')}${btn('丢弃后离开','leave-discard')}${btn('留在当前','dialog-close')}</div>`);return;}S.form=null;S.frame=id;if(id!=='VP04'){S.visualLoop=false;view.setVisualU(0);}if(id==='VP05'&&S.pendingHall){S.selectedHall=S.pendingHall;S.pendingHall=null;$('hall-label').textContent='厂房 '+S.selectedHall;}
  if(id==='VP07')S.lod='simplified';if(id==='VP08')S.lod='region';if(id==='VP09')S.canvas='multi';else if(['VP05','VP06','VP07','VP08'].includes(id))S.canvas='line';
  if(['VP11','VP12','VP13','VP21'].includes(id)&&!S.run)loadSchedule();if(id==='VP10'){S.source='input';S.dock=240;}if(id==='VP06')view.inspect(S.selected);
  history.replaceState(null,'',`?frame=${id}`);render();log('navigate',{frame:id});}
function resetProjectSession(project,revision,savedRevision,viewState){S.project=project;S.revision=revision;S.savedRevision=savedRevision;S.undo=[];S.redo=[];S.form=null;S.run=null;S.compute=null;S.packResult=null;S.paperProcessSample=null;S.sampleRuns=[];S.play=false;S.visualLoop=false;S.inputPreview=null;S.inputBase=null;S.inputDelta=null;S.arrivalPreviewSelection=null;S.drag=null;S.source='input';S.axis='factory';S.axisWindow=[0,600];S.axisReturn=null;S.axisHistory=[];S.expanded=false;S.selectedEvent=null;S.selectedJob=null;S.waitMappingMessage=null;S.selectedUnit=null;S.definitionDraft=null;S.category=null;S.endpointEvent=null;S.connectSource=null;S.copyPreview=null;S.adoptionPreview=null;S.pendingSelection=null;S.pendingFrame=null;S.pendingHall=null;S.pendingAction=null;S.pendingSeek=null;S.conflict=false;S.seekToken++;S.comparisonUsed=false;S.lineSelected=false;S.clipSelection=null;S.selected=project.devices[0]?.id||'';S.selectedHall='A';S.paperBindingTargetId=null;S.canvas='line';S.lod='detailed';S.tool='select';S.agent={preview:null,built:false,rounds:0,scenario:'initial',stop:null,accepted:null};S.pendingOpen=null;S.pendingProjectAction=null;S.newProjectApproved=false;if(viewState)Object.assign(S,viewState);S.flow=D.flows.some(f=>f.id===viewState?.flow)?viewState.flow:(D.flows.find(f=>f.frames[0]===viewState?.frame)||D.flows.find(f=>f.frames.includes(viewState?.frame))||D.flows[0]).id;S.viewTime=0;invalidatePaper();imageAsset=S.project.media.imageAsset||null;view.setProject(S.project);view.setVisualU(0);}
function startFlow(id){resetProjectSession(seed(),1,0);S.flow=id;S.newProjectApproved=D.flows.find(f=>f.id===id).frames[0]==='VP01';go(D.flows.find(f=>f.id===id).frames[0],true);view.resetCamera();}
function selectDevice(id){if(id==='REGION_LINE01'){showDialog('区域成员 · 保留当前选择',msg('区域只是显示聚合。选择成员才进入设备配置，当前身份 '+esc(S.selected)+' 保留。')+S.project.devices.filter(d=>S.project.lineMembers.includes(d.id)).map(d=>`<button data-region-member="${esc(d.id)}">${esc(d.id+' '+d.name)}</button>`).join('')+btn('留在当前','dialog-close'));return;}
 if(S.tool==='connect'){if(S.connectSource&&S.connectSource!==id){recordEdit();S.project.connections.push([S.connectSource,id]);S.revision++;S.connectSource=null;view.setProject(S.project);notice('已添加原型物流连接');render();}else {S.connectSource=id;notice('选择目的设备');}return;}
  if(S.form?.dirty){S.pendingSelection=id;showDialog('切对象前处理字段',msg('当前表单未应用；选中对象和未提交字段先保留。')+btn('应用后切换','selection-apply')+btn('丢弃后切换','selection-discard')+btn('留在当前','dialog-close'));return;}
  const device=S.project.devices.find(d=>d.id===id);if(device?.model==='sealer'&&packagingTargetId()!==id){const changed=S.project.paper.ack||S.project.paper.bound;S.paperBindingTargetId=id;invalidatePaper();if(changed)S.revision++;}S.visualLoop=false;view.setVisualU(0);S.selected=id;S.lineSelected=false;S.form=null;bindSelectedInstance();if(['VP05','VP07','VP08'].includes(S.frame))go('VP03',true);else render();}
function moveDevice(id,x,y){if(S.tool!=='move')return;if(S.form?.dirty){action('move-device',{move:{id,x,y}});return;}if(id==='REGION_LINE01'){notice('区域是显示聚合；使用整线移动入口修改成员布局');return;}if(x<0||y<0||x>S.project.dimensions[0]||y>S.project.dimensions[1]){notice('移动预览超出场地；原布局保留');return;}commit('pose',{...S.project.devices.find(d=>d.id===id),x:Math.round(x*10)/10,y:Math.round(y*10)/10},id);render();}
function registerSample(){S.sampleRuns??=[];const record=copy(S.run),i=S.sampleRuns.findIndex(r=>r.id===record.id);if(i<0)S.sampleRuns.push(record);else S.sampleRuns[i]=record;}
function clearSampleContext(){S.seekToken++;S.pendingSeek=null;S.play=false;S.viewTime=0;S.selectedEvent='';S.endpointEvent=null;S.selectedJob=null;S.waitMappingMessage=null;S.inputPreview=null;S.drag=null;S.axis='factory';S.axisWindow=[0,600];S.axisHistory=[];}
function loadSchedule(variant='baseline'){clearSampleContext();const data=copy(D.schedules.find(r=>r.scenario===variant));S.run={id:'样例-L03-'+variant,source_kind:'manual_expected',inputRevision:'frozen-L03-'+variant,data,computedUntil:data.observation_end_ms/1000,partial:false};S.source='actual';S.viewTime=0;S.axis='factory';S.seekToken++;S.pendingSeek=null;S.selectedEvent='';S.endpointEvent=null;S.selectedJob=null;S.waitMappingMessage=null;S.inputPreview=null;S.drag=null;registerSample();log('load_manual_schedule',{variant,product_Run:false,not_computed_from_current_draft:true});}
function render(){bindSelectedInstance();document.body.style.setProperty('--left',(S.leftVisible?S.leftWidth:32)+'px');document.body.style.setProperty('--right',(S.rightVisible?S.rightWidth:32)+'px');document.body.style.setProperty('--dock',S.dock+'px');document.body.style.setProperty('--description',S.descriptionWidth+'px');document.body.classList.toggle('collapsed-desc',!S.descriptionVisible);document.body.classList.toggle('collapsed-time',!S.timelineVisible);document.body.classList.toggle('hidden-dock',!S.descriptionVisible&&!S.timelineVisible);
  $('project-title').textContent=S.project.title;$('save-indicator').textContent=S.revision===S.savedRevision?' · 原型快照已保存':' · 未保存';$('context-label').textContent=`${S.frame} ${frame(S.frame)?.title||''}　|　r${S.revision}　|　${S.run?.id||'无样例结果'}`;
  $('status').textContent=`原型草稿r${S.revision} | ${S.form?.dirty?'表单未应用':'表单无未提交更改'} | ${S.compute?.state||'没有计算任务'} | 选中${S.selected}`;
  $('source-label').textContent='手工预期/自建交互例；产品实际结果为空';renderMenus();renderLibrary();renderProperties();renderWorkspace();renderTimeline();renderTools();view.setProject(S.project);view.setLOD(S.lod);view.select(S.selected);view.setVisible(!taskMode());view.setTime(S.viewTime,S.run?.data,S.selectedUnit);
  document.querySelectorAll('.canvas-tabs>button').forEach((b,n)=>b.classList.toggle('active',S.canvas===(n===0?'line':'multi')));document.querySelectorAll('.lod button').forEach(b=>b.classList.toggle('active',b.dataset.action==='lod-'+S.lod));
  window.S04_STATE={frame:S.frame,revision:S.revision,formDirty:!!S.form?.dirty,run:S.run?.id||null,viewTime:S.viewTime,axis:S.axis,compute:S.compute?.state||null,actual_product_runtime:null};}
function renderMenus(){const menus=['文件','编辑','视图','工程','模块','仿真','窗口','帮助'];$('menus').innerHTML=menus.map((m,n)=>`<button data-menu="${m}" data-index="${n}">${m}</button>`).join('');}
function openMenu(name,index){document.querySelector('.menu')?.remove();const choices={
  '文件':[['新建空工程','new-project'],['保存原型快照','save'],['打开原型JSON','open-project'],['未保存离开','unsaved-leave']],
  '编辑':[['撤销草稿编辑','undo'],['重做','redo']], '视图':[['默认相机','camera-reset'],['背面','camera-back'],['底部','camera-bottom'],['近景','camera-near'],['文字150%','text-large'],['文字100%','text-normal'],['主轴放大显示','expand-dock']],
  '工程':[['物品 / BOM / 订单','frame-VP02'],['跨厂供货','frame-VP09'],['输入排期','frame-VP10'],['纸包装专业工程','frame-VP18']], '模块':[['设备创作','frame-VP04'],['采用变更预览','adoption-preview']],
  '仿真':[['载入L03手工基线','sample-baseline'],['载入到料延迟预期','sample-delayed'],['模拟任务状态交互','compute-demo'],['取消示例任务','compute-cancel'],['计算截断例','sample-partial'],['续算快照替换例','sample-resume'],['DTC03已知/未知裁窗','sample-partial-window'],['DTC11续算25s仍为前缀','sample-resume-prefix'],['DTC02裁窗手工例','sample-clip'],['DRF06阶段/占用手工例','sample-calendar'],['FC15末刻接受点','sample-end']],
  '窗口':[[`${S.leftVisible?'✓':'□'} 工程与库`,'toggle-left'],[`${S.rightVisible?'✓':'□'} 对象属性`,'toggle-right'],[`${S.timelineVisible?'✓':'□'} 时间轴`,'toggle-timeline'],[`${S.descriptionVisible?'✓':'□'} 事件描述`,'toggle-description'],['恢复默认布局','layout-reset']],
  '帮助':[['原型范围与来源','about'],['插入修订冲突示例','inject-conflict'],['保存失败示例','save-failure'],['查看交互记录','interaction-log']]};
  const div=document.createElement('div');div.className='menu';div.style.left=(8+index*48)+'px';div.innerHTML=choices[name].map(([l,a])=>btn(l,a)).join('');$('menus').append(div);}
function renderLibrary(){if(!S.leftVisible){$('library').innerHTML=`<div class="rail">${btn('›','toggle-left')}工程与九类库</div>`;return;}
  $('library').innerHTML=`<h3>工程对象${btn('‹','toggle-left')}</h3><div class="flow-select"><select aria-label="任务链" id="flow-picker">${D.flows.map(f=>`<option value="${f.id}" ${f.id===S.flow?'selected':''}>${f.id} ${f.title}</option>`).join('')}</select><div class="steps">${btn('开始本任务链','flow-start',true)}${btn('下一步','flow-next')}</div></div><div class="tree">${btn('⌄ '+esc(S.project.title),'frame-VP05')}${btn('厂房 A / 流水线','line-canvas')}${S.project.devices.map(d=>`<button class="indent ${d.id===S.selected?'selected':''}" data-device="${d.id}">${esc(d.name)} · ${d.id}</button>`).join('')}</div><h3>模块库 · 九类定义</h3><div class="sub">采用定义不新增库存</div><div class="library-section">${['物品','固定设备','资源','任务','工艺','物流','厂房与组合','专业计算','表现素材'].map((c,n)=>`<button data-category="${n}">› ${c}<small>自定义</small></button>`).join('')}</div><h3>24帧设计状态</h3><div class="frame-nav">${D.frames.map(f=>`<button data-action="frame-${f.id}" title="${esc(f.title)}" ${f.id===S.frame?'class="active"':''}>${f.id}</button>`).join('')}</div>`;}
function renderProperties(){if(!S.rightVisible){$('properties').innerHTML=`<div class="rail">${btn('‹','toggle-right')}属性</div>`;return;}
  const device=S.project.devices.find(d=>d.id===S.selected);let body;
  if(!device&&S.frame!=='VP09'){body='<h2>未选择当前草稿设备</h2>'+msg('空工程可继续搭建；从九类库创作或采用设备，再编辑配置。旧样例不会把同名对象自动接到当前草稿。');}
  else if(S.frame==='VP09'){const p=edit('supply');body=`<h2>跨厂供货 S01</h2>${row('物品','item',p.item)}${row('日目标','quantity',p.quantity,'件')}${row('装载时间','loading',p.loading,'s')}${row('去程时间','outbound',p.outbound,'s')}${row('卸载时间','unloading',p.unloading,'s')}${row('返程时间','returning',p.returning,'s')}${msg('目标不是实际到货；装卸、去返程与接受分别记录。')}<div class="actions">${btn('应用更改','apply',true)}${btn('放弃更改','discard')}</div>`;}
  else if(taskMode()){body=`<h2>${esc(device?.name||'工程上下文')}</h2>${row('实例ID','id',S.selected,'',true)}${row('定义版本','version',device?.version||'','',true)}${msg('任务工作区是唯一编辑区；这里仅显示上下文。')}<h4>结果归属</h4>${table(['属性','值'],[['修订',S.revision],['样例结果',S.run?.id||'未载入'],['产品Run','尚未实现'],['人工认可',S.project.paper.ack?'原型用途认可':'未认可']])}${btn('返回流水线','frame-VP05')}`;}
  else{const p=edit('pose');body=`<h2>${esc(device?.name||'设备')} ${S.selected}</h2><div class="actions">${btn('设备配置','frame-VP03')}${btn('表现编辑','frame-VP04')}</div>${section('身份 / 布局',row('实例ID','id',device?.id,'',true)+row('定义版本','version',device?.version,'',true)+row('X','x',p?.x,'m')+row('Y','y',p?.y,'m')+row('Z','z',p?.z,'m')+row('绕Z朝向','yaw',p?.yaw,'°'))}${msg('坐标为厂房m / Z向上。应用草稿不影响已载入样例。')}<div class="actions">${btn('应用更改','apply',true)}${btn('放弃更改','discard')}</div>${section('来源',`现有${esc(device?.model)}.glb，版本${esc(device?.version)}。<br>业务参数/数量为自建设计样例。`)}`;}
  $('properties').innerHTML=`<h3>对象属性${btn('›','toggle-right')}</h3><div class="property-body">${body}</div>`;}
const taskMode=()=> !['VP05','VP06','VP07','VP08'].includes(S.frame)||S.canvas==='multi';
