function net(p){const w=Number(p.width)||1,d=Number(p.depth)||1,h=Number(p.height)||1,scale=Math.min(500/(w+2*h),260/(d+2*h));
 if(S.frame!=='VP19'){const bw=w*scale,bd=d*scale,bh=h*scale,x=350-bw/2,y=190-bd/2;return `<svg class="paper-net" viewBox="0 0 700 400" data-step="manufacturing"><text x="20" y="28">${esc(p.mechanism)} / ${w}×${d}×${h} mm · 自建制造层示意</text><rect data-panel="BASE" x="${x}" y="${y}" width="${bw}" height="${bd}"/><rect data-panel="NORTH" x="${x}" y="${y-bh}" width="${bw}" height="${bh}"/><rect data-panel="SOUTH" x="${x}" y="${y+bd}" width="${bw}" height="${bh}"/><rect data-panel="WEST" x="${x-bh}" y="${y}" width="${bh}" height="${bd}"/><rect data-panel="EAST" x="${x+bw}" y="${y}" width="${bh}" height="${bd}"/><text x="${x+8}" y="${y+bd/2}">PANEL-BASE</text><path class="fold" d="M${x} ${y}h${bw}v${bd}h-${bw}Z"/><text x="20" y="380">五板片展示代理；不是专业算法返回的完整刀模</text></svg>`;}
 const u=Number(p.angle)/90,a=u*Math.PI/2,s=Math.min(2,360/(w+d+2*h)),co=Math.cos(a),si=Math.sin(a);const project=v=>[350+(v[0]-v[1])*.8*s,250+(v[0]+v[1])*.3*s-v[2]*.9*s];const polygons={BASE:[[-w/2,-d/2,0],[w/2,-d/2,0],[w/2,d/2,0],[-w/2,d/2,0]],NORTH:[[-w/2,-d/2,0],[w/2,-d/2,0],[w/2,-d/2-h*co,h*si],[-w/2,-d/2-h*co,h*si]],SOUTH:[[-w/2,d/2,0],[w/2,d/2,0],[w/2,d/2+h*co,h*si],[-w/2,d/2+h*co,h*si]],WEST:[[-w/2,-d/2,0],[-w/2,d/2,0],[-w/2-h*co,d/2,h*si],[-w/2-h*co,-d/2,h*si]],EAST:[[w/2,-d/2,0],[w/2,d/2,0],[w/2+h*co,d/2,h*si],[w/2+h*co,-d/2,h*si]]};const colors=['#d4b384','#dcc199','#c9a675','#e1c8a6','#b99a70'];const step=p.angle===90?'forming':'opening';S.paperProcessSample={source_kind:'independent_UI_visual_fixture',job_ref:{id:'UI-PAPER-JOB',revision:1},step_id:step,progress:u,panel_poses:Object.entries(polygons).map(([id,vertices])=>({panel_id:id,pose:{translation:{x:vertices.reduce((a,v)=>a+v[0],0)/4,y:vertices.reduce((a,v)=>a+v[1],0)/4,z:vertices.reduce((a,v)=>a+v[2],0)/4},rotation:{x:id==='NORTH'?-Math.sin(a/2):id==='SOUTH'?Math.sin(a/2):0,y:id==='WEST'?Math.sin(a/2):id==='EAST'?-Math.sin(a/2):0,z:0,w:id==='BASE'?1:Math.cos(a/2)},scale:{x:1,y:1,z:1}}})),unit:'mm',coordinate_system:'right_handed_z_up',actual_provider:false};return `<svg class="paper-net" viewBox="0 0 700 400" data-step="${step}" data-progress="${u}"><text x="20" y="28">step=${step} / u=${u.toFixed(2)} · 独立UI姿态样例</text>${Object.entries(polygons).map(([id,verts],i)=>`<polygon data-panel="${id}" points="${verts.map(v=>project(v).join(',')).join(' ')}" fill="${colors[i]}" stroke="#8a7256"/>`).join('')}<text x="20" y="365">panel_id锁定板片；u是步骤参数，不是生产时间。有限预览不证明无干涉。</text></svg>`;}
