  const jobs=S.run?.data.jobs||[],work=jobs.filter(j=>['assembly','inspection','packing','rework','reinspection'].includes(j.kind)),waits=jobs.filter(j=>j.kind==='cart_receive_wait');let active=0,peak=0;for(const [,delta]of work.flatMap(j=>[[j.start_ms,1],[j.end_ms,-1]]).sort((a,b)=>a[0]-b[0]||a[1]-b[1])){active+=delta;peak=Math.max(peak,active);}const summary=S.source==='input'||!S.run?'':`<button class="group-summary" data-action="timeline-expand">手工例：工作${work.length}段 · 并行峰值${peak} · 接收等待${waits.length}段；展开明细</button>`;let tracks=tr(`${btn(S.expanded?'⌄':'›','timeline-expand')}<button data-action="select-group">总装检查与包装线</button>`,summary,true);
