function seek(time){if(!S.run||time<0||time>S.run.computedUntil){notice('超出已知样例范围，未查询未计算时点');return;}const token=++S.seekToken,runId=S.run.id;S.pendingSeek=time;log('prototype_seek_candidate',{time,runId});setTimeout(()=>{if(token!==S.seekToken||runId!==S.run?.id){log('seek_reply_discarded',{runId});return;}S.viewTime=time;S.pendingSeek=null;view.setTime(time,S.run.data,S.selectedUnit);renderTimeline();$('status').textContent=`原型r${S.revision} | ${S.run.id} | 已确认观察${time}s`;window.S04_STATE.viewTime=time;log('seek_confirmed',{time,runId});},70);}
