document.addEventListener('scroll',e=>{if(e.target.classList?.contains('time-body')&&e.target.offsetParent){S.timelineScroll??={};S.timelineScroll[e.target.dataset.scrollKey]=e.target.scrollTop;}},true);
for(const [id,dimension] of [['left-split','leftWidth'],['right-split','rightWidth'],['description-split','descriptionWidth'],['dock-grip','dock']]){$(id).addEventListener('pointerdown',e=>{const start=e.clientX,sy=e.clientY,value=S[dimension];const move=p=>{S[dimension]=dimension==='dock'?Math.max(120,Math.min(320,value+sy-p.clientY)):Math.max(dimension==='descriptionWidth'?240:180,Math.min(dimension==='descriptionWidth'?480:520,value+(dimension==='rightWidth'?start-p.clientX:p.clientX-start)));document.body.style.setProperty(dimension==='dock'?'--dock':dimension==='descriptionWidth'?'--description':dimension==='leftWidth'?'--left':'--right',S[dimension]+'px');};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);render();};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);e.preventDefault();});}
$('project-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const v=JSON.parse(await file.text());if(v.document_kind!=='S04_interaction_prototype_project_state'||!Array.isArray(v.project?.devices)||!Array.isArray(v.project?.dimensions)||!v.project?.media||!Array.isArray(v.project.definitions)||!Array.isArray(v.project.lineMembers)||!v.project.paper||!v.project.order||!v.project.goal||!v.project.supply||!Array.isArray(v.project.arrivals)||!Array.isArray(v.project.connections)||!v.view||!D.frames.some(f=>f.id===v.view.frame)||!Number.isInteger(v.revision))throw Error('不是本轮完整原型快照');if(v.view.selected&&!v.project.devices.some(d=>d.id===v.view.selected))throw Error('选择对象不在候选工程中');if(!v.project.instanceState)v.project.instanceState={[v.view.selected]:{config:copy(v.project.device),media:copy(v.project.media)}};S.pendingOpen={doc:v,name:file.name};confirmOpenSnapshot();}catch(err){notice('打开失败，原工程保留：'+err.message);}finally{e.target.value='';}});
$('media-file').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/gif'].includes(file.type)){notice('此原型只读取PNG/JPEG/GIF，不执行上传脚本');return;}const project=S.project,deviceId=S.selected,media=S.project.media;const reader=new FileReader();reader.onload=()=>{if(S.project!==project||S.selected!==deviceId||S.project.media!==media){notice('素材读取时工程或设备已改变，未写入当前上下文');return;}recordEdit();imageAsset=reader.result;media.imageAsset=imageAsset;S.revision++;render();log('media_uploaded',{name:file.name,type:file.type,deviceId,persisted_in_prototype:true});};reader.readAsDataURL(file);});
